class Solution { fun maxProductPath(grid:Array<IntArray>):Int{val rows=grid.size;val cols=grid[0].size;val maximum=Array(rows){LongArray(cols)};val minimum=Array(rows){LongArray(cols)};maximum[0][0]=grid[0][0].toLong();minimum[0][0]=grid[0][0].toLong();for(row in 0 until rows)for(col in 0 until cols){if(row==0&&col==0)continue;var max=Long.MIN_VALUE;var min=Long.MAX_VALUE;val value=grid[row][col].toLong();if(row>0){max=maxOf(max,maximum[row-1][col]*value,minimum[row-1][col]*value);min=minOf(min,maximum[row-1][col]*value,minimum[row-1][col]*value)};if(col>0){max=maxOf(max,maximum[row][col-1]*value,minimum[row][col-1]*value);min=minOf(min,maximum[row][col-1]*value,minimum[row][col-1]*value)};maximum[row][col]=max;minimum[row][col]=min};val result=maximum[rows-1][cols-1];return if(result<0)-1 else (result%1_000_000_007L).toInt()} }
